&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +36 (2d8+11/19-20 plus saignement) et 4 griffes, +36 (2d6+11/19-20)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Espace occup&#233;&lt;/b&gt; 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) ;  Allonge 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; rugissement abyssal, &lt;a class=&quot;pagelink&quot; href=&quot;Saignement-(Capacit&#233;).html&quot; title=&quot;Saignement (Ext)&quot;&gt;saignement&lt;/a&gt; (2d6), &lt;a class=&quot;pagelink&quot; href=&quot;Sous-Type-D&#233;modande.html&quot; title=&quot;D&#233;modande (sous-type)&quot;&gt;attaque voleuse de foi&lt;/a&gt; (DD 27), &lt;a class=&quot;pagelink&quot; href=&quot;&#201;ventration-(Capacit&#233;).html&quot; title=&quot;&#201;ventration (Ext)&quot;&gt;&#233;ventration&lt;/a&gt; (4 griffes, 2d6+16), plongeon &#233;tourdissant
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;NLS&lt;/a&gt; 20 ; &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;concentration&lt;/a&gt; +23)
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
Constant — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Bien.html&quot; title=&quot;D&#233;tection du Bien&quot;&gt;d&#233;tection du Bien&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-Lucide.html&quot; title=&quot;Vision lucide&quot;&gt;vision lucide&lt;/a&gt;&lt;/i&gt;
&lt;/div&gt;
&lt;div class=&quot;BDsorts&quot;&gt;
1/jour — &lt;a class=&quot;pagelink&quot; href=&quot;Convocation-(Capacit&#233;).html&quot; title=&quot;Convocation (Mag)&quot;&gt;convocation&lt;/a&gt; (niveau 8, 1d8 &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;modande-Goudronneux.html&quot; title=&quot;D&#233;modande, D&#233;modande goudronneux&quot;&gt;d&#233;modandes goudronneux&lt;/a&gt; ou 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;modande-Visqueux.html&quot; title=&quot;D&#233;modande, D&#233;modande visqueux&quot;&gt;d&#233;modandes visqueux&lt;/a&gt; ou 1 &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;modande-Hirsute.html&quot; title=&quot;D&#233;modande, D&#233;modande hirsute&quot;&gt;d&#233;modandes hirsute&lt;/a&gt; 75%)
&lt;/div&gt;
